FAlsControlRigInput UAlsAnimationInstance::GetControlRigInput() const
{
	// In addition to being on the ground, allow pelvis offset if the
	// character is in the air, but only if GroundPredictionAmount is non-zero.

	const auto PelvisOffsetAmount{
		UAlsMath::Clamp01(PoseState.GroundedAmount + PoseState.InAirAmount * InAirState.GroundPredictionAmount)
	};

	return {
		.bUseHandIkBones = !IsValid(Settings) || Settings->General.bUseHandIkBones,
		.bUseFootIkBones = !IsValid(Settings) || Settings->General.bUseFootIkBones,
		.bFootTransformsValid = static_cast<bool>(FeetState.bValid),
		.VelocityBlendForwardAmount = GroundedState.VelocityBlend.ForwardAmount,
		.VelocityBlendBackwardAmount = GroundedState.VelocityBlend.BackwardAmount,
		.SpineYawAngle = SpineState.FinalYawAngle,
		.PelvisOffsetAmount = PelvisOffsetAmount,
		.FootLeftLocation{FVector{FeetState.Left.FinalLocation}},
		.FootLeftRotation{FQuat{FeetState.Left.FinalRotation}},
		.FootRightLocation{FVector{FeetState.Right.FinalLocation}},
		.FootRightRotation{FQuat{FeetState.Right.FinalRotation}},
	};
}

	const auto FootLeftTargetTransform{
		Mesh->GetSocketTransform(Settings->General.bUseFootIkBones
			                         ? UAlsConstants::FootLeftIkBoneName()
			                         : UAlsConstants::FootLeftVirtualBoneName())
	};

	FeetState.Left.TargetLocationWorldSpace = FootLeftTargetTransform.GetLocation();
	FeetState.Left.TargetRotationWorldSpace = FootLeftTargetTransform.GetRotation();

	const auto FootRightTargetTransform{
		Mesh->GetSocketTransform(Settings->General.bUseFootIkBones
			                         ? UAlsConstants::FootRightIkBoneName()
			                         : UAlsConstants::FootRightVirtualBoneName())
	};

	FeetState.Right.TargetLocationWorldSpace = FootRightTargetTransform.GetLocation();
	FeetState.Right.TargetRotationWorldSpace = FootRightTargetTransform.GetRotation();
}

{
	return;
}

FeetState.FootPlantedAmount = FMath::Clamp(GetCurveValue(UAlsConstants::FootPlantedCurveName()), -1.0f, 1.0f);
FeetState.FeetCrossingAmount = GetCurveValueClamped01(UAlsConstants::FeetCrossingCurveName());

const auto ComponentTransform{GetProxyOnAnyThread<FAnimInstanceProxy>().GetComponentTransform()};

FAlsFootUpdateContext Context{
	.ComponentTransform{ComponentTransform},
	.ComponentTransformInverse{ComponentTransform.Inverse()},
	.DeltaTime = DeltaTime
};

Context.FootState = &FeetState.Left;
Context.IkAmount = GetCurveValueClamped01(UAlsConstants::FootLeftIkCurveName());
Context.LockAmount = GetCurveValueClamped01(UAlsConstants::FootLeftLockCurveName());

ProcessFootLockTeleport(Context);
ProcessFootLockBaseChange(Context);
RefreshFootLock(Context);

Context.FootState = &FeetState.Right;
Context.IkAmount = GetCurveValueClamped01(UAlsConstants::FootRightIkCurveName());
Context.LockAmount = GetCurveValueClamped01(UAlsConstants::FootRightLockCurveName());

ProcessFootLockTeleport(Context);

for (int32 VirtualBoneIdx = 0; VirtualBoneIdx < NumVirtualBones; ++VirtualBoneIdx)
{
	const int32 ActualIndex = VirtualBoneIdx + RawRefBoneInfo.Num();
	const FVirtualBone& VB = Skeleton->GetVirtualBones()[VirtualBoneIdx];

	const int32 SourceIndex = GetRawSourceBoneIndex(Skeleton, VB.SourceBoneName);	//-V595
	const int32 ParentIndex = FindBoneIndex(VB.SourceBoneName);
	const int32 TargetIndex = FindBoneIndex(VB.TargetBoneName);
	if(ParentIndex != INDEX_NONE && TargetIndex != INDEX_NONE)
	{
		FinalRefBoneInfo.Add(FMeshBoneInfo(VB.VirtualBoneName, VB.VirtualBoneName.ToString(), ParentIndex));

		const FTransform TargetCS = GetComponentSpaceTransform(ComponentSpaceFlags, ComponentSpaceTransforms, *this, TargetIndex);
		const FTransform SourceCS = GetComponentSpaceTransform(ComponentSpaceFlags, ComponentSpaceTransforms, *this, SourceIndex);

		FTransform VBTransform = TargetCS.GetRelativeTransform(SourceCS);

		const int32 NewBoneIndex = FinalRefBonePose.Add(VBTransform);
		FinalNameToIndexMap.Add(VB.VirtualBoneName) = NewBoneIndex;
		RequiredVirtualBones.Add(NewBoneIndex);
		UsedVirtualBoneData.Add(FVirtualBoneRefData(NewBoneIndex, SourceIndex, TargetIndex));
	}

//Build Virtual Bones
if (VBCompactPoseData.Num() > 0)
{
	FCSPose<FCompactPose> CSPose1;
	CSPose1.InitPose(InOutPose);

	FCSPose<FCompactPose> CSPose2;
	if (bInterpolateT)
	{
		CSPose2.InitPose(Key2Pose);
	}

	for (FVirtualBoneCompactPoseData& VB : VBCompactPoseData)
	{
		FTransform Source = CSPose1.GetComponentSpaceTransform(VB.SourceIndex);
		FTransform Target = CSPose1.GetComponentSpaceTransform(VB.TargetIndex);
		InOutPose[VB.VBIndex] = Target.GetRelativeTransform(Source);

		if (bInterpolateT)
		{
			FTransform Source2 = CSPose2.GetComponentSpaceTransform(VB.SourceIndex);
			FTransform Target2 = CSPose2.GetComponentSpaceTransform(VB.TargetIndex);
			Key2Pose[VB.VBIndex] = Target2.GetRelativeTransform(Source2);
		}

	else
	{
		for (int32 i = 1; i < InFillComponentSpaceTransformsRequiredBones.Num(); i++)
		{
			const int32 BoneIndex = InFillComponentSpaceTransformsRequiredBones[i];
			FTransform* SpaceBase = ComponentSpaceData + BoneIndex;

			FPlatformMisc::Prefetch(SpaceBase);

#if DO_GUARD_SLOW
			// Mark bone as processed
			BoneProcessed[BoneIndex] = 1;
#endif
			// For all bones below the root, final component-space transform is relative transform * component-space transform of parent.
			const int32 ParentIndex = GetRefSkeleton().GetParentIndex(BoneIndex);
			FTransform* ParentSpaceBase = ComponentSpaceData + ParentIndex;
			FPlatformMisc::Prefetch(ParentSpaceBase);

#if DO_GUARD_SLOW
			// Check the precondition that Parents occur before Children in the RequiredBones array.
			checkSlow(BoneProcessed[ParentIndex] == 1);
#endif
			FTransform::Multiply(SpaceBase, LocalTransformsData + BoneIndex, ParentSpaceBase);

			SpaceBase->NormalizeRotation();

			checkSlow(SpaceBase->IsRotationNormalized());
			checkSlow(!SpaceBase->ContainsNaN());

    let Ok(target) = transforms.compute_global_transform(bones.target(side, use_ik_bones)) else {
        continue;
    };
    let (foot_state, ik_amount, lock_amount) = match side {
        0 => (&mut lock_state.left, left_ik_amount, left_lock_amount),
        _ => (&mut lock_state.right, right_ik_amount, right_lock_amount),
    };
    if became_valid {
        reset_foot_lock_to_target(foot_state, target.translation(), target.rotation());
    }
    refresh_foot_lock(
        foot_state,
        target.translation(),
        target.rotation(),
        ik_amount,
        lock_amount,
        settings.allow_foot_lock,
        lock_input.moving_smooth,
        *locomotion == LocomotionState::Grounded,
        became_valid,
        dt,
        current_base,
    );
    let chain = bones.chain(side);
    let thigh_axis_pelvis_space = Vec3::from(if side == 0 {
        profile.0.target.foot_left_thigh_axis_pelvis_space
    } else {
        profile.0.target.foot_right_thigh_axis_pelvis_space
    });
    if let Ok(thigh_parent) = parents.get(chain.thigh)
        && let Ok(pelvis_world) = transforms.compute_global_transform(thigh_parent.0)
    {
        source_constrain_foot_lock(
            foot_state,
            &armature,
            &pelvis_world,
            thigh_axis_pelvis_space,
            settings,
        );
    }
}
if let Some(input) = rig_input.as_mut() {
    input.foot_transforms_valid = lock_state.valid;
    input.foot_left_location_armature = armature_point_from_world(&armature, WorldPoint(lock_state.left.final_location)).0;
    input.foot_left_rotation_armature = armature_rotation_from_world(&armature, WorldRotation(lock_state.left.final_rotation)).0;
    input.foot_right_location_armature = armature_point_from_world(&armature, WorldPoint(lock_state.right.final_location)).0;
    input.foot_right_rotation_armature = armature_rotation_from_world(&armature, WorldRotation(lock_state.right.final_rotation)).0;
}
dynamic_transition.update(

    mut commands: Commands,
    characters: Query<(Entity, Option<&AlsControlRigSettings>, Has<AlsControlRigInput>, Option<&AlsFootTargetSelection>), With<AlsCharacter>>,
) {
    for (entity, settings, has_input, selection) in &characters {
        let settings = settings.copied().unwrap_or_default();
        if !has_input {
            commands.entity(entity).insert(AlsControlRigInput {
                use_hand_ik_bones: settings.use_hand_ik_bones,
                use_foot_ik_bones: settings.use_foot_ik_bones,
                ..default()
            });
        }
        if selection.is_none_or(|selection| selection.use_ik_bones != settings.use_foot_ik_bones) {
            commands.entity(entity).insert(AlsFootTargetSelection {
                use_ik_bones: settings.use_foot_ik_bones,
            });
        }
    }
}

    .with_mask(crate::als::character::AlsCollisionLayer::Visibility);
use bevy_animation_graph::core::edge_data::DataValue;
for (field, value) in [
    ("b_use_hand_ik_bones", DataValue::Bool(input.use_hand_ik_bones)),
    ("b_use_foot_ik_bones", DataValue::Bool(input.use_foot_ik_bones)),
    ("b_foot_transforms_valid", DataValue::Bool(input.foot_transforms_valid)),
    ("velocity_blend_forward_amount", DataValue::F32(input.velocity_blend_forward_amount)),
    ("velocity_blend_backward_amount", DataValue::F32(input.velocity_blend_backward_amount)),
    ("spine_yaw_angle", DataValue::F32(-input.spine_yaw_angle_degrees)),
    ("pelvis_offset_amount", DataValue::F32(input.pelvis_offset_amount)),
    ("foot_left_location", DataValue::Vec3(input.foot_left_location_armature)),
    ("foot_left_rotation", DataValue::Quat(input.foot_left_rotation_armature)),
    ("foot_right_location", DataValue::Vec3(input.foot_right_location_armature)),
    ("foot_right_rotation", DataValue::Quat(input.foot_right_rotation_armature)),
] {
    set_source_frame_input(&mut player, &format!("control_rig_input.{field}"), value);
}
set_source_frame_input(&mut player, crate::extensions::root_graph_boundaries::RIG_GAME_WORLD_KEY, true);
